head='''<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><defs><filter id="shadow" x="-30%" y="-30%" width="160%" height="165%"><feDropShadow dx="0" dy="7" stdDeviation="4" flood-color="#172438" flood-opacity=".25"/></filter></defs><g stroke="#293C57" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" filter="url(#shadow)">'''
