assets={}
for key,body in shapes.items():
 svg=head+body+foot
 (out/(key+'.svg')).write_text(svg,encoding='utf-8')
 raw=cairosvg.svg2png(bytestring=svg.encode(),output_width=160,output_height=160)
 im=Image.open(io.BytesIO(raw)).convert('RGBA')
 im.save(out/(key+'.webp'),format='WEBP',quality=84,method=6)
 dat=(out/(key+'.webp')).read_bytes()
 assets[key]='data:image/webp;base64,'+base64.b64encode(dat).decode()
(P/'client/src/gameverse-art-v27.js').write_text('export const GAMEVERSE_ART_V27 = '+json.dumps(assets,separators=(',',':'),ensure_ascii=False)+';\n',encoding='utf-8')
print(len(shapes),'new art families',sum((out/(k+'.webp')).stat().st_size for k in shapes),'compressed bytes')
